<script setup lang="ts">
import RevisitExport from'./RevisitExport.vue';
import{treatmentEntry,type TreatmentEntry}from'./use-treatment-handoff';
import{useFollowupConfirmations,selectFollowupNode}from'./use-followup-confirmations';
import{useFollowupPlanChoices}from'./use-followup-plan-choices';
import{useFollowupPlanPage}from'./use-followup-plan-page';import FollowupPlanHistory from'./FollowupPlanHistory.vue';
import{useFollowupSources}from'./use-followup-sources';
import{useFollowupCommand}from'./use-followup-command';import{useSalesScope}from'./use-sales-scope';
import FollowupJournalPanel from './FollowupJournalPanel.vue';
import{ref,computed,onMounted,onBeforeUnmount,watch}from'vue';import{PhoneCall,ClipboardList,RefreshCw,ArrowLeft,Plus,X,Check,Clock3,MessageCircle}from'@lucide/vue';
const linkedTreatment=ref<any>(null);let handoffGeneration=0;
const props=defineProps<{staff:any;treatmentEntry?:TreatmentEntry|null}>(),emit=defineEmits(['unauthorized','return-clinical']);const clinics=ref<any[]>([]),clinic=ref(''),date=ref(''),functions=ref<string[]>([]),ready=ref(false),loading=ref(false),error=ref(''),notice=ref(''),section=ref('tasks'),filter=ref('all'),rows=ref<any[]>([]),catalogue=ref<any[]>([]),workers=ref<any[]>([]),detail=ref<any>(null),records=ref<any[]>([]),mode=ref(''),form=ref<any>({});
useFollowupConfirmations(()=>mode.value,()=>form.value);
const identity=()=>JSON.stringify([props.staff?.accountId,props.staff?.employeeId]),scope=useSalesScope(()=>JSON.stringify([identity(),clinic.value])),authScope=useSalesScope(identity),retryConfirmed=ref(false),opening=ref(false);
const command=useFollowupCommand({owner:()=>props.staff?.accountId&&props.staff?.employeeId?props.staff:null,storage:()=>sessionStorage,read:p=>request(p),send:(p,b)=>request(p,b),completed:async(path,r)=>{const current=authScope.capture();mode.value='';await refresh(true);if(current()&&path==='/tasks')await select(r.id);}}),{pending}=command,busy=computed(()=>command.busy.value||opening.value);
async function retryOriginal(){if(!retryConfirmed.value)return;const current=authScope.capture();retryConfirmed.value=false;const saved=await command.retry();if(current()&&(saved||pending.value))mode.value='';}
const sourceChoices=useFollowupSources({context:()=>JSON.stringify([identity(),section.value,mode.value]),clinic:()=>clinic.value,date:()=>date.value,read:(p,signal)=>request(p,undefined,signal),cleared:()=>{if(mode.value==='task'&&!form.value.taskId){form.value.treatmentId='';treatmentChanged();form.value.plannedAt='';form.value.nextAction='';}},loaded:list=>workers.value=list,invalidated:status=>{if(status===401||status===403){detail.value=null;workers.value=[];mode.value='';}else if(mode.value==='task'&&!form.value.taskId){form.value.treatmentId='';treatmentChanged();}}}),sources=sourceChoices.items;
const planDirectory=useFollowupPlanPage({account:()=>props.staff,clinic:()=>clinic.value,context:()=>section.value,read:(p,signal)=>request(p,undefined,signal),invalidated:status=>{if(status===401||status===403){catalogue.value=[];mode.value='';}}});
watch(section,()=>{if(ready.value&&section.value==='plans')void planDirectory.load();});
const journalPanel=ref<any>(null),pageBusy=ref({contacts:false,issues:false});
async function moreRecords(kind:'contacts'|'issues'){const valid=scope.begin('journal-'+kind,()=>JSON.stringify([section.value,detail.value?.followup_id])),current=detail.value,cursor=current?.[kind+'Cursor'];if(!current||!cursor||pageBusy.value[kind])return;pageBusy.value[kind]=true;error.value='';try{const b=await request('/tasks/'+current.followup_id+'/journal?'+new URLSearchParams({kind,cursor}));if(!valid()||detail.value!==current)return;if(b.taskVersion!==current.version)throw new ApiError(409,'随访已变化，请刷新后重读。');current[kind].push(...b.items);current[kind+'Cursor']=b.nextCursor;}catch(e){if(valid()&&detail.value===current){error.value=explain(e);if(e instanceof ApiError&&e.status===409){current.contactsCursor=null;current.issuesCursor=null;}}}finally{if(valid.active())pageBusy.value[kind]=false;}}
function historyUnauthorized(status:number){clearQueue();planDirectory.reset();catalogue.value=[];detail.value=null;records.value=[];mode.value='';if(status===401)emit('unauthorized');else error.value='当前随访供阅范围已变化，请重新读取。';}
const has=(fn:string)=>functions.value.includes(fn),canManagePlan=computed(()=>has('followup.plan.manage')),canWork=computed(()=>has('followup.manage')),local=(s?:string)=>new Date((s?Date.parse(s):Date.now())+8*3600000).toISOString().slice(0,19),instant=(s:string)=>s?new Date(s+'+08:00').toISOString():null,full=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
const search=ref(''),fromDate=ref(''),toDate=ref(''),responsible=ref('all'),nextCursor=ref<string|null>(null),matched=ref(0),asOf=ref(''),queueLoading=ref(false),queueLoaded=ref(false),loadedQuery=ref('');
const emptySummary=()=>({total:0,due:0,issues:0,unreached:0,reached:0}),summary=ref(emptySummary());let queueGeneration=0;
const visible=computed(()=>rows.value),query=()=>({state:filter.value,q:search.value.trim(),fromDate:fromDate.value,toDate:toDate.value,responsible:responsible.value}),queueDirty=computed(()=>loadedQuery.value!==JSON.stringify(query()));
const responsibleOptions=computed(()=>{const m=new Map(workers.value.map(w=>[w.id,w.name]));for(const r of rows.value)m.set(r.responsibleId,r.responsibleName);return[...m].map(([id,name])=>({id,name}));});
function clearQueue(){queueGeneration++;rows.value=[];summary.value=emptySummary();matched.value=0;nextCursor.value=null;asOf.value='';queueLoaded.value=false;queueLoading.value=false;}
async function loadQueue(more=false){if(!clinic.value||!has('followup.read'))return;if(more&&queueDirty.value)return;if(!more)clearQueue();const valid=scope.begin('queue',()=>JSON.stringify([section.value,query()])),gen=++queueGeneration,selected=clinic.value,conditions=query();queueLoading.value=true;error.value='';
 try{const params=new URLSearchParams({clinicId:selected,...conditions});if(more&&nextCursor.value)params.set('cursor',nextCursor.value);const b=await request('/tasks?'+params);if(!valid()||gen!==queueGeneration||selected!==clinic.value)return;rows.value=more?[...rows.value,...b.items]:b.items;summary.value=b.summary;matched.value=b.matched;nextCursor.value=b.nextCursor;asOf.value=b.asOf;loadedQuery.value=JSON.stringify(conditions);queueLoaded.value=true;}
 catch(e){if(valid()&&gen===queueGeneration){if(e instanceof ApiError&&[401,403,409].includes(e.status)){clearQueue();detail.value=null;}error.value=explain(e);}}
 finally{if(valid.active()&&gen===queueGeneration)queueLoading.value=false;}}
function resetQueue(){search.value='';fromDate.value='';toDate.value='';responsible.value='all';filter.value='all';loadQueue();}
onBeforeUnmount(clearQueue);
const latestPlans=planDirectory.items;
const selectedTreatment=computed(()=>sources.value.find(t=>t.id===form.value.treatmentId)||(linkedTreatment.value?.id===form.value.treatmentId?linkedTreatment.value:null)||(detail.value&&detail.value.treatment_id===form.value.treatmentId?{id:detail.value.treatment_id,version:detail.value.treatmentVersion,doctorId:detail.value.doctorId,doctorName:detail.value.doctorName,itemName:detail.value.itemName,itemId:detail.value.itemId,patientName:detail.value.patientName}:null));
watch(()=>JSON.stringify([identity(),clinic.value,date.value,props.treatmentEntry]),()=>{handoffGeneration++;linkedTreatment.value=null;},{flush:'sync'});watch(()=>JSON.stringify([section.value,mode.value]),()=>{handoffGeneration++;},{flush:'sync'});
const choiceContext=()=>JSON.stringify([identity(),section.value,mode.value,form.value.taskId,form.value.treatmentId]);
const planChoices=useFollowupPlanChoices({context:choiceContext,clinic:()=>clinic.value,target:()=>{const t=selectedTreatment.value;return mode.value==='task'&&t?{treatmentId:t.id,version:t.version,...(form.value.taskId?{taskId:form.value.taskId,taskVersion:form.value.version}:{})}:null;},read:(p,signal)=>{const k=choiceContext();return request(p,undefined,signal,()=>choiceContext()===k);},invalidated:status=>{form.value.nodeKey='';form.value.arrangementConfirmed=false;if(status===401||status===403)mode.value='';}});
const nodeOptions=computed(()=>planChoices.items.value.flatMap(p=>p.nodes.map((n:any)=>({key:p.plan_version_id+':'+n.node_id,label:`${p.retained_only?'已采用原节点（保留） · ':''}${p.item_name} · 方案${p.plan_id.slice(0,6)}第${p.version_no}版 · ${n.time_arrangement}`,p,n}))));
watch(()=>[planChoices.loaded.value,JSON.stringify(nodeOptions.value.map(n=>n.key))],()=>{if(planChoices.loaded.value&&form.value.nodeKey&&!nodeOptions.value.some(n=>n.key===form.value.nodeKey))treatmentChanged();});

class ApiError extends Error{constructor(public status:number,m:string){super(m);}}
async function request(path:string,body?:any,signal?:AbortSignal,current:()=>boolean=()=>true){const valid=scope.capture(),c=new AbortController(),timer=setTimeout(()=>c.abort(),12000),cancel=()=>c.abort();signal?.addEventListener('abort',cancel,{once:true});if(signal?.aborted)c.abort();try{const r=await fetch('/api/v1/followup'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:c.signal});const b=await r.json().catch(()=>({}));if(!r.ok){if(valid()&&current()&&!signal?.aborted&&(r.status===401||r.status===403)){error.value=b.message||'当前工作范围已变化，请重新登录或读取。';clearQueue();detail.value=null;records.value=[];sources.value=[];workers.value=[];mode.value='';if(r.status===401)emit('unauthorized');}throw new ApiError(r.status,b.message||'请求失败。');}return b;}finally{clearTimeout(timer);signal?.removeEventListener('abort',cancel);}}
const planRead=(p:string,signal:AbortSignal)=>request(p,undefined,signal);
const explain=(e:unknown)=>e instanceof Error?e.message:'操作失败。';
async function initialize(){const current=authScope.begin('initialize');loading.value=true;command.restore();try{const b=await request('/bootstrap');if(!current())return;functions.value=b.functions;clinics.value=b.clinics;const target=props.treatmentEntry?treatmentEntry(props.treatmentEntry,props.staff):null;if(target&&!b.clinics.some((c:any)=>c.id===target.clinicId))throw Error('当前没有原治疗所属诊所的随访范围。');clinic.value=target?.clinicId||b.clinics[0]?.id||'';date.value=target?.date||b.today;section.value=has('followup.read')?'tasks':'plans';ready.value=true;await refresh(true);if(target&&current())await readTreatmentEntry();}catch(e){if(current())error.value=explain(e);}finally{if(current.active())loading.value=false;}}
async function loadSources(more=false){if(!has('followup.read')||!clinic.value)return false;return sourceChoices.load(more===true);}
async function refresh(force=false){if(force!==true&&(mode.value||busy.value))return;if(!ready.value)return initialize();if(!clinic.value)return;const current=scope.begin('refresh',()=>section.value);loading.value=true;error.value='';try{if(section.value==='plans'){await planDirectory.load();return;}if(has('followup.read')){await loadQueue();if(!current())return;await loadSources();if(current()&&detail.value)await select(detail.value.followup_id);}}catch(e){if(current()){error.value=explain(e);clearQueue();detail.value=null;}}finally{if(current.active())loading.value=false;}}
async function select(id:string){const current=scope.begin('detail',()=>section.value);detail.value=null;records.value=[];try{const b=await request('/tasks/'+id);if(!current())return;detail.value=b.item;records.value=b.records;workers.value=b.workers;}catch(e){if(current()){error.value=explain(e);detail.value=null;}}}
const chosenNode=computed(()=>nodeOptions.value.find(o=>o.key===form.value.nodeKey));
function chooseNode(){selectFollowupNode(form.value,chosenNode.value);}
function treatmentChanged(){form.value.nodeKey='';form.value.doctorInstruction='';form.value.plannedContent='';form.value.instructionConfirmed=false;form.value.arrangementConfirmed=false;}
async function open(m:string,p?:any,linked=false){if(busy.value||pending.value||command.isBlocked()){error.value='请先核查原提交记录。';return;}error.value='';if(m==='plan'){const current=scope.begin('open',()=>JSON.stringify([section.value,detail.value?.followup_id]));opening.value=true;try{const loaded=await request('/plan-items?clinicId='+clinic.value);if(!current())return;catalogue.value=loaded.items;}catch(e){if(current())error.value=explain(e);return;}finally{if(current.active())opening.value=false;}}mode.value=m;const d=detail.value;
 if(m==='plan')form.value={planId:p?.plan_id||null,version:Number(p?.row_version)||0,itemId:p?.item_id||'',effectiveFrom:p?local(new Date(Date.now()+120000).toISOString()):local(),effectiveTo:'',enabled:p?.enabled??true,nodes:p?p.nodes.map((n:any)=>({timeArrangement:n.time_arrangement,contactContent:n.contact_content,clinicalPurpose:n.clinical_purpose})):[{timeArrangement:'',contactContent:'',clinicalPurpose:''}],doctorRequirementsConfirmed:false,reason:''};
 if(m==='toggle')form.value={id:p.plan_id,version:Number(p.row_version),enabled:!p.enabled,reason:''};
 if(m==='task')form.value={taskId:p?.followup_id||null,version:p?.version||0,treatmentId:p?.treatment_id||'',nodeKey:p?.node_id?p.plan_version_id+':'+p.node_id:'',doctorInstruction:p?.doctor_instruction||'',instructionConfirmed:false,plannedAt:p?local(p.planned_at):'',plannedContent:p?.planned_content||'',responsibleId:p?.responsible_id||props.staff.employeeId,nextAction:p?.next_action||'',arrangementConfirmed:false,reason:''};
 if(m==='task'&&!form.value.taskId&&!linked)void loadSources();
 if(m==='contact')form.value={contactedAt:local(),channel:'',reached:'',feedback:'',nextAction:d.next_action||'',problems:[]};
 if(m==='issue')form.value={id:p.followup_issue_id,doctorId:p.doctor_id||'',conclusion:p.progress_conclusion||'',resolve:'no',resolvedAt:'',clinicalRecordId:'',clinicalBasis:'',feedbackVerified:false};
}
async function readTreatmentEntry(){if(!props.treatmentEntry||busy.value||pending.value||mode.value||command.isBlocked())return false;let e:TreatmentEntry;try{e=treatmentEntry(props.treatmentEntry,props.staff);}catch(err){error.value=explain(err);return false;}if(clinic.value!==e.clinicId||date.value!==e.date){error.value='交接范围已改变，请返回原诊所和日期重新核对。';return false;}const current=scope.begin('treatment-entry',()=>JSON.stringify([mode.value,section.value,date.value])),generation=handoffGeneration,valid=Object.assign(()=>current()&&generation===handoffGeneration,{active:current.active});linkedTreatment.value=null;opening.value=true;try{const b=await request('/treatments/'+e.treatmentId+'/source?'+new URLSearchParams({clinicId:e.clinicId,visitId:e.visitId}),undefined,undefined,valid);if(!valid())return false;const t=b.treatment;if(t?.id!==e.treatmentId||t.visitId!==e.visitId||t.clinicId!==e.clinicId||t.version!==e.treatmentVersion)throw Error('原治疗版本或归属已变化，请返回诊疗核对后再安排。');linkedTreatment.value=t;workers.value=b.workers;return true;}catch(err){if(valid()){linkedTreatment.value=null;error.value=explain(err);}return false;}finally{if(valid.active())opening.value=false;}}
async function openLinkedTask(){if(!canWork.value||mode.value||busy.value||pending.value||command.isBlocked())return;const valid=scope.capture();if(!await readTreatmentEntry()||!valid()||!linkedTreatment.value)return;const t=linkedTreatment.value;await open('task',undefined,true);if(!valid()||mode.value!=='task'||linkedTreatment.value!==t)return;form.value.treatmentId=t.id;treatmentChanged();form.value.responsibleId='';form.value.plannedAt='';form.value.plannedContent='';}
function returnClinical(){if(!busy.value&&!loading.value&&!mode.value&&!pending.value&&!command.isBlocked())emit('return-clinical');}
function close(){if(!busy.value&&!pending.value)mode.value='';}
async function send(path:string,body:any,_label:string){const current=authScope.capture();retryConfirmed.value=false;const saved=await command.submit(path,body);if(current()&&(saved||pending.value))mode.value='';return saved;}
async function save(){const f=form.value,d=detail.value,requestId=crypto.randomUUID();try{
 if(mode.value==='plan')return send('/plans',{...f,requestId,clinicId:clinic.value,effectiveFrom:instant(f.effectiveFrom),effectiveTo:instant(f.effectiveTo),reason:f.reason||null},'方案新版本已保存，既有任务不被改写。');
 if(mode.value==='toggle')return send(`/plans/${f.id}/enabled`,{requestId,version:f.version,enabled:f.enabled,reason:f.reason},f.enabled?'方案已启用；后端已检查范围冲突。':'方案已停用；既有任务和历史保留。');
 if(mode.value==='task'){if(!planChoices.loaded.value||planChoices.loading.value||planChoices.error.value)throw Error('请先读取并核对本次治疗的适用方案。');if(f.nodeKey&&!nodeOptions.value.some(n=>n.key===f.nodeKey))throw Error('原方案节点不在本次选项中，请重新读取。');const t=selectedTreatment.value;if(!t)throw Error('请选择有权的实际治疗。');const [planVersionId,nodeId]=f.nodeKey?f.nodeKey.split(':'):[null,null];return send('/tasks',{requestId,taskId:f.taskId,version:f.version,treatmentId:t.id,treatmentVersion:t.version,planVersionId,nodeId,doctorInstruction:f.doctorInstruction||null,instructionDoctorId:planVersionId?null:t.doctorId,instructionConfirmed:f.instructionConfirmed,plannedAt:instant(f.plannedAt),plannedContent:f.plannedContent,responsibleId:f.responsibleId,nextAction:f.nextAction||null,arrangementConfirmed:f.arrangementConfirmed,reason:f.reason||null},'随访安排已保存，尚不代表联系已完成。');}
 if(mode.value==='contact')return send(`/tasks/${d.followup_id}/contacts`,{requestId,version:d.version,contactedAt:instant(f.contactedAt),channel:f.channel,reached:f.reached==='yes',feedback:f.feedback,nextAction:f.nextAction||null,problems:f.problems.map((p:any)=>({problem:p.problem,doctorId:p.doctorId||null}))},'实际联系已追加；成功联系与专业问题分别更新。');
 if(mode.value==='issue')return send(`/tasks/${d.followup_id}/issues/${f.id}`,{requestId,version:d.version,doctorId:f.doctorId||null,conclusion:f.conclusion,resolve:f.resolve==='yes',resolvedAt:instant(f.resolvedAt),clinicalRecordId:f.clinicalRecordId||null,clinicalBasis:f.clinicalBasis||null,feedbackVerified:f.feedbackVerified},'专业问题跟进已保存，原医生结论与核实登记人员分别留存。');
 }catch(e){error.value=explain(e);}}
watch(identity,()=>{opening.value=false;clinics.value=[];clinic.value='';functions.value=[];catalogue.value=[];sources.value=[];workers.value=[];detail.value=null;records.value=[];clearQueue();pageBusy.value={contacts:false,issues:false};mode.value='';form.value={};retryConfirmed.value=false;notice.value='';error.value='';ready.value=false;loading.value=false;void initialize();},{flush:'sync'});
watch(clinic,()=>{opening.value=false;clearQueue();detail.value=null;records.value=[];sources.value=[];workers.value=[];catalogue.value=[];pageBusy.value={contacts:false,issues:false};mode.value='';form.value={};retryConfirmed.value=false;},{flush:'sync'});
onMounted(initialize);defineExpose({refresh});
</script>
<template><section v-if="props.treatmentEntry" class="b-card" style="padding:20px;margin-bottom:20px"><h2>从实际治疗接续随访</h2><p v-if="linkedTreatment">{{linkedTreatment.patientName}} · {{linkedTreatment.itemName}} · 当前治疗第{{linkedTreatment.version}}版</p><p v-else>请读取原治疗并核对。不会自动选择方案、联系时间或负责人。</p><button type="button" class="b-button outline small" :disabled="busy||loading||!!mode||!!pending||command.isBlocked()" @click="readTreatmentEntry">重读原治疗</button><button v-if="canWork" type="button" class="b-button small" :disabled="busy||loading||!!mode||!!pending||command.isBlocked()" @click="openLinkedTask">核对后填写随访安排</button><button type="button" class="b-button outline small" :disabled="busy||loading||!!mode||!!pending||command.isBlocked()" @click="returnClinical">返回原诊疗就诊</button></section><div class="followup-workspace">
 <div v-if="error" class="b-alert error" role="alert">{{error}}<button @click="error=''">关闭</button></div><div v-if="notice" class="b-alert success" role="status"><Check :size="17"/>{{notice}}<button @click="notice=''">关闭</button></div><p v-if="command.error.value" class="b-alert error" role="alert">{{command.error.value}}</p><p v-if="command.notice.value" class="b-alert success" role="status">{{command.notice.value}}</p><div v-if="pending" class="b-alert warning"><strong>{{pending.summary}}</strong><p>原请求 {{pending.body.requestId}}</p><template v-if="pending.phase==='pending'"><p>先只读核实原请求，不会重复登记联系或处理结论。</p><button type="button" class="b-button small" :disabled="busy" @click="retryConfirmed=false;command.verify()">只读核实原提交</button><template v-if="command.status.value?.state==='completed'"><p>已核实原结果 {{command.status.value.resultId}} · 第 {{command.status.value.version}} 版 · {{full(command.status.value.completedAt)}}</p><button type="button" class="b-button small" :disabled="busy" @click="command.acknowledge">已核对，清理提示</button></template><template v-else-if="command.status.value?.state==='not_found'"><p>暂未查到本请求的成功凭据，可能仍在处理，不能据此断定未办理。重试会发送原POST，不是只读查询。</p><label class="b-checkbox"><input v-model="retryConfirmed" type="checkbox" :disabled="busy"/><span>已核对原办理，按原请求重试</span></label><button type="button" class="b-button small" :disabled="busy||!retryConfirmed" @click="retryOriginal">重试原提交</button></template></template><template v-else><p>原办理已明确{{pending.phase==='confirmed'?'成功':'被拒绝'}}，仅本机提示待清理。</p><button type="button" class="b-button small" :disabled="busy" @click="command.cleanup">清理本机提示</button></template></div>
 <div class="f-tabs"><button v-if="has('followup.read')" :class="{active:section==='tasks'}" @click="section='tasks'"><PhoneCall :size="17"/>随访待办</button><button :class="{active:section==='plans'}" @click="section='plans';detail=null"><ClipboardList :size="17"/>随访方案</button></div>
 <div class="b-card f-toolbar"><label>诊所<select :disabled="busy||!!pending||!!mode" v-model="clinic" @change="detail=null;clearQueue();refresh"><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button class="b-button outline small" :disabled="loading||busy||!!mode" @click="refresh()"><RefreshCw :size="15"/>刷新</button></div>
 <div v-if="!ready" class="b-card b-empty">{{loading?'正在连接…':'未取得工作范围'}}<button class="b-button outline" :disabled="loading" @click="initialize">重新连接</button></div><div v-else-if="!clinics.length" class="b-card b-empty">当前账号没有随访或方案范围。</div>
 <template v-else-if="section==='plans'"><section class="b-card c-block"><div class="f-list-head"><div><h2>按医生要求配置的方案</h2><p>仅供工作人员核对，修改或停用不改写已安排的患者随访。</p></div><button v-if="canManagePlan" class="b-button small" :disabled="busy||!!pending" @click="open('plan')"><Plus :size="15"/>新建方案</button></div><div class="f-toolbar"><label>治疗项目或方案编号<input v-model="planDirectory.search.value" maxlength="100"/></label><label>启用状态<select v-model="planDirectory.state.value"><option value="all">全部</option><option value="active">启用</option><option value="inactive">停用</option></select></label><button type="button" class="b-button outline small" :disabled="planDirectory.loading.value||busy" @click="planDirectory.load()">查询方案</button><button type="button" class="b-button outline small" :disabled="planDirectory.loading.value||busy" @click="planDirectory.clearFilters()">清空方案条件</button></div><p v-if="planDirectory.error.value" class="b-alert error" role="alert">{{planDirectory.error.value}}</p><p v-if="planDirectory.dirty.value" class="b-help">条件尚未应用，请查询方案。</p><p v-if="planDirectory.summary.value" class="b-help">线索匹配 {{planDirectory.summary.value.total}} 项方案：启用 {{planDirectory.summary.value.active}} · 停用 {{planDirectory.summary.value.inactive}}；统计先于状态筛选。</p><p v-if="planDirectory.loading.value&&!latestPlans.length" class="b-help" role="status">正在读取方案…</p><p v-else-if="planDirectory.asOf.value&&!latestPlans.length" class="b-empty">当前条件下没有方案，请调整查询条件。</p><article v-for="p in latestPlans" :key="p.plan_id" class="fu-plan"><div class="care-order-head"><div><small>方案 {{p.plan_id.slice(0,8).toUpperCase()}} · 第 {{p.version_no}} 版</small><h3>{{p.item_name}}</h3></div><span class="b-pill" :class="p.enabled?'active':''">{{p.enabled?'允许新选择':'已停用'}}</span></div><p class="b-help">生效 {{full(p.effective_from)}} — {{p.effective_to?full(p.effective_to):'无固定终点'}}；是否当前适用由提交时重验。</p><div v-for="n in p.nodes" :key="n.node_id" class="fu-node"><strong>{{n.time_arrangement}}</strong><p>{{n.contact_content}}</p><small>医生要求 / 临床目的：{{n.clinical_purpose}}</small></div><div v-if="canManagePlan" class="care-actions"><button class="b-button outline small" :disabled="busy||!!pending" @click="open('plan',p)">另存新版本</button><button class="b-button outline small" :disabled="busy||!!pending" @click="open('toggle',p)">{{p.enabled?'停用新选择':'启用方案'}}</button></div><FollowupPlanHistory :account="props.staff" :clinic-id="clinic" :plan-id="p.plan_id" :read="planRead" @invalidated="historyUnauthorized"/></article><p v-if="planDirectory.asOf.value" class="b-help">已显示 {{latestPlans.length}} / {{planDirectory.total.value}} 项方案</p><button v-if="planDirectory.next.value" type="button" class="b-button outline small" :disabled="planDirectory.loading.value||planDirectory.dirty.value||busy" @click="planDirectory.load(true)">继续加载方案</button></section></template>
 <template v-else-if="!detail">
 <p class="fu-summary-scope">范围统计：按检索、计划日期和责任范围汇总全部可见任务；下方状态筛选不改变这组统计。<span v-if="asOf">读取 {{full(asOf)}}（北京时间）</span></p>
 <div class="fu-metrics fu-queue-metrics"><div><ClipboardList :size="19"/><strong>{{queueLoaded?summary.total:'—'}}</strong><span>范围内全部任务</span></div><div><Clock3 :size="19"/><strong>{{queueLoaded?summary.due:'—'}}</strong><span>到期且尚无成功联系</span></div><div><MessageCircle :size="19"/><strong>{{queueLoaded?summary.issues:'—'}}</strong><span>仍有医生待处理问题</span></div><div><Check :size="19"/><strong>{{queueLoaded?summary.reached:'—'}}</strong><span>已有成功联系事实</span></div></div>
 <section class="b-card f-list"><div class="f-list-head"><div><h2>诊后随访安排</h2><p>未解专业问题优先，按计划时间与稳定标识排序；成功联系与问题解决分别核对。</p></div><button v-if="canWork" class="b-button small" :disabled="busy||!!pending" @click="open('task')"><Plus :size="15"/>安排随访</button></div>
 <form class="fu-queue-filter" @submit.prevent="loadQueue()"><label>患者姓名或治疗项目<input aria-label="患者姓名或治疗项目" v-model="search" maxlength="100" placeholder="输入姓名或项目，不检索电话号码"/></label><label>计划开始日期<input aria-label="计划开始日期" type="date" v-model="fromDate"/></label><label>计划结束日期<input aria-label="计划结束日期" type="date" v-model="toDate"/></label><label>责任范围<select aria-label="责任范围" v-model="responsible" @change="loadQueue()"><option value="all">全部可见任务</option><option value="mine">仅本人负责</option><option v-for="w in responsibleOptions" :key="w.id" :value="w.id">{{w.name}}</option></select></label><label>联系与问题状态<select aria-label="联系与问题状态" v-model="filter" @change="loadQueue()"><option value="all">全部状态</option><option value="due">到期未成功联系</option><option value="issues">有医生待处理问题</option><option value="unreached">尚无成功联系</option><option value="reached">已有成功联系</option></select></label><div class="fu-queue-actions"><button class="b-button small" :disabled="queueLoading">查询待办</button><button type="button" class="b-button outline small" :disabled="queueLoading" @click="resetQueue">清空筛选</button></div></form>
 <p v-if="queueDirty&&queueLoaded" class="fu-queue-hint">筛选内容已变化，请点击“查询待办”；下方仍是上次已应用的查询。</p><p v-if="queueLoading" class="fu-queue-hint" role="status">正在读取有权待办…</p>
 <div class="b-table-scroll"><table><thead><tr><th>患者 / 治疗</th><th>计划联系</th><th>责任人</th><th>联系事实</th><th>专业问题</th><th>操作</th></tr></thead><tbody><tr v-for="q in visible" :key="q.id"><td><strong>{{q.patientName}}</strong><small>{{q.itemName}}</small></td><td>{{full(q.plannedAt)}}<small v-if="q.due">已到计划时间</small></td><td>{{q.responsibleName}}</td><td><span class="b-pill" :class="q.contactState==='reached'?'active':''">{{q.contactState==='reached'?'已有成功联系':'尚无成功联系'}}</span></td><td>{{q.openIssues>0?q.openIssues+' 项待医生处理':'无登记待处理问题'}}</td><td><button class="b-button outline small" @click="select(q.id)">打开随访</button></td></tr><tr v-if="!visible.length&&!queueLoading"><td colspan="6" class="b-empty">{{queueLoaded?'当前条件下没有有权随访安排。':'请查询待办。'}}</td></tr></tbody></table></div>
 <div class="fu-queue-footer"><span v-if="queueLoaded">已读取 {{rows.length}} / {{matched}} 条符合状态筛选的任务</span><button v-if="nextCursor" class="b-button outline small" :disabled="queueLoading||queueDirty" @click="loadQueue(true)">读取更多待办</button></div></section></template>
 <template v-else><button class="c-back" @click="detail=null"><ArrowLeft :size="16"/>返回随访待办</button><section class="b-card c-patient"><div><h2>{{detail.patientName}}</h2><p>{{detail.itemName}} · 实施 {{full(detail.performedAt)}} · {{detail.doctorName}}</p></div><div class="fu-status"><span class="b-pill" :class="detail.contactState==='reached'?'active':''">{{detail.contactState==='reached'?'已有成功联系事实':'尚无成功联系登记'}}</span><span class="b-pill">{{detail.openIssues>0?detail.openIssues+'项医生待处理':'无登记待处理专业问题'}}</span></div></section><RevisitExport :key="staff.accountId+staff.employeeId+clinic+detail.followup_id+detail.version" :source="{version:1,clinicId:clinic,followupId:detail.followup_id,patientName:detail.patientName,contact:detail.phone||'',doctorName:detail.doctorName}" :blocked="busy||loading||!!mode||!!pending||command.isBlocked()"/><section class="b-card c-block"><div class="f-list-head"><div><h2>本次随访安排</h2><p>计划 {{full(detail.planned_at)}} · {{detail.responsibleName}}负责</p></div><button v-if="canWork" class="b-button outline small" :disabled="busy||!!pending" @click="open('task',detail)">核对调整安排</button></div><div class="fu-body"><p class="fu-content">{{detail.planned_content}}</p><p v-if="detail.plan">采用方案第 {{detail.plan.version_no}} 版 · {{detail.node.time_arrangement}}<small>{{detail.plan.enabled?'方案允许新选择':'方案已停用，保留本任务原采用'}}</small></p><p v-else>医生个别要求：{{detail.doctor_instruction}}</p><div class="fu-contact-info"><span>联系电话<strong>{{detail.phone||'未登记，联系前核实'}}</strong></span><span>联系偏好<strong>{{detail.contactPreference||'尚未登记，联系前核实'}}</strong></span></div><p v-if="detail.next_action" class="care-note">后续安排：{{detail.next_action}}</p></div></section>
 <section class="b-card c-block"><div class="f-list-head"><div><h2>真实联系记录</h2><p>只登记工作人员实际联系，不执行外呼或发送消息。</p></div><button v-if="canWork" class="b-button small" :disabled="busy||!!pending" @click="open('contact')">登记实际联系</button></div><p class="fu-page-count">已显示 {{detail.contacts.length}} / {{detail.contactsTotal}} 条实际联系。整体联系状态按全部记录计算。</p><p v-if="!detail.contacts.length" class="b-empty">尚无实际联系登记；已安排不表示已联系。</p><article v-for="c in detail.contacts" :key="c.followup_contact_id" class="fu-contact"><div><strong>{{{phone:'电话',message:'消息',onsite:'当面',other:'其他'}[c.channel]}} · {{full(c.contacted_at)}}</strong><span class="b-pill" :class="c.reached_patient?'active':''">{{c.reached_patient?'本次已联系到患者':'本次未联系到患者'}}</span></div><p>{{c.result_feedback}}</p><small>{{c.employee_name}}登记 · 登记时点 {{full(c.registered_at)}}<span v-if="c.next_action"> · 后续：{{c.next_action}}</span></small></article><button v-if="detail.contactsCursor" class="b-button outline small fu-page-more" :disabled="pageBusy.contacts" @click="moreRecords('contacts')">继续读取联系记录</button></section>
 <section class="b-card c-block"><div class="f-list-head"><div><h2>需要医生处理的问题</h2><p>转交或普通回复不等于解决；依据由护士或授权协助前台核实登记。</p></div></div><p class="fu-page-count">已显示 {{detail.issues.length}} / {{detail.issuesTotal}} 项问题，未解决问题优先；顶部待处理数按全部问题计算。</p><p v-if="!detail.issues.length" class="b-empty">无登记的专业待处理问题，不代表已排除所有临床风险。</p><article v-for="i in detail.issues" :key="i.followup_issue_id" class="fu-issue"><div class="care-order-head"><strong>{{i.problem}}</strong><span class="b-pill" :class="i.resolved_at?'active':''">{{i.resolved_at?'已核实解决':'待医生处理'}}</span></div><button class="f-text" @click="journalPanel?.openIssue(i.followup_issue_id,i.problem)">追查本问题处理经过</button><p>接手医生：{{i.doctor_name||'尚待明确转交'}}</p><p>{{i.progress_conclusion||'尚无跟进反馈'}}</p><div v-if="i.resolved_at" class="fu-resolved"><strong>医生实际处理 {{full(i.resolved_at)}}</strong><p>{{i.clinical_basis}}</p><small>{{i.recorder_name}}核实登记于 {{full(i.recorded_at)}}；登记人不是临床判断人。</small></div><button v-else-if="canWork" class="b-button outline small" :disabled="busy||!!pending" @click="open('issue',i)">登记跟进 / 核实医生反馈</button></article><button v-if="detail.issuesCursor" class="b-button outline small fu-page-more" :disabled="pageBusy.issues" @click="moreRecords('issues')">继续读取问题目录</button></section><FollowupJournalPanel ref="journalPanel" :key="detail.followup_id" :task-id="detail.followup_id" :version="detail.version" @unauthorized="historyUnauthorized"/></template>
 <div v-if="mode" class="b-backdrop"><form class="b-dialog fu-dialog" role="dialog" aria-modal="true" @submit.prevent="save"><button type="button" class="b-close" aria-label="关闭随访办理" :disabled="busy||!!pending" @click="close"><X :size="21"/></button><div class="b-eyebrow">FOLLOW-UP CARE</div><h2>{{{plan:'根据医生要求配置方案',toggle:form.enabled?'启用随访方案':'停用方案的新选择',task:form.taskId?'核对调整随访':'安排诊后随访',contact:'登记已经发生的联系',issue:'核实登记医生问题反馈'}[mode]}}</h2><div v-if="error" class="b-alert error" role="alert">{{error}}</div>
 <template v-if="mode==='plan'"><label>治疗项目<select v-model="form.itemId" required :disabled="!!form.planId"><option value="">请选择适用项目</option><option v-for="i in catalogue" :key="i.id" :value="i.id">{{i.name}}</option></select></label><p class="b-help">适用诊所：{{clinics.find(c=>c.id===clinic)?.name}}。第一批每方案一个明确诊所，不默认为所有门店。</p><div class="b-two-fields"><label>生效起点<input type="datetime-local" step="1" v-model="form.effectiveFrom" required/></label><label>生效终点（可空）<input type="datetime-local" step="1" v-model="form.effectiveTo"/></label></div><div class="c-subheading"><strong>医生要求的联系节点</strong><button type="button" class="b-button outline small" :disabled="form.nodes.length>=12" @click="form.nodes.push({timeArrangement:'',contactContent:'',clinicalPurpose:''})"><Plus :size="14"/>加节点</button></div><div v-for="(n,k) in form.nodes" :key="k" class="c-treatment-edit"><label>时间安排说明<input v-model="n.timeArrangement" required maxlength="500" placeholder="填写已核实的医生要求，不自动套用医学间隔"/></label><label>联系内容要求<textarea v-model="n.contactContent" rows="2" required maxlength="2000"/></label><label>已核实的医生要求 / 临床目的<textarea v-model="n.clinicalPurpose" rows="2" required maxlength="2000"/></label><button v-if="form.nodes.length>1" type="button" class="f-text" @click="form.nodes.splice(k,1)">移除此未保存节点</button></div><label class="b-checkbox"><input type="checkbox" v-model="form.enabled"/><span>允许在生效区间内供新随访选择。</span></label><label v-if="form.planId">改版原因<textarea v-model="form.reason" required rows="2"/></label><label class="b-checkbox"><input type="checkbox" v-model="form.doctorRequirementsConfirmed" required/><span>管理人员已核实医生提供的具体要求，节点不是系统推定的医学规则。</span></label></template>
 <template v-if="mode==='toggle'"><p class="b-help">{{form.enabled?'启用会重验当前及未来同范围冲突。':'停用仅阻止新选择，不删除版本、任务或已发生联系。'}}</p><label>启停原因<textarea v-model="form.reason" required rows="3"/></label></template>
 <template v-if="mode==='task'"><div v-if="!form.taskId"><label>治疗所在的实际到院日期<input type="date" v-model="date" @change="loadSources()"/></label><label>查找患者、治疗项目或医生<input v-model="sourceChoices.search.value" maxlength="100" placeholder="可留空查询当日有权来源" @keydown.enter.prevent="loadSources()"/></label><button type="button" class="b-button outline small" :disabled="busy||sourceChoices.loading.value" @click="loadSources()">查找治疗来源</button><p v-if="sourceChoices.error.value" class="b-alert error" role="alert">{{sourceChoices.error.value}}</p><p v-if="sourceChoices.loading.value" class="b-help" role="status">正在读取治疗来源…</p><p v-else-if="linkedTreatment&&form.treatmentId===linkedTreatment.id" class="b-help" role="status">已按编号读取原治疗；如需改选，可查找其他有权来源。</p><p v-else-if="!sourceChoices.loaded.value" class="b-help" role="status">条件已变更，请查找治疗来源。</p><p v-else class="b-help">已加载 {{sources.length}} / {{sourceChoices.total.value}} 项治疗来源。按实际到院日期查询。</p><button v-if="sourceChoices.next.value" type="button" class="b-button outline small" :disabled="busy||sourceChoices.loading.value" @click="loadSources(true)">继续加载治疗来源</button><label>患者与实际治疗<select aria-label="患者与实际治疗" :disabled="sourceChoices.loading.value" v-model="form.treatmentId" required @change="treatmentChanged"><option v-if="linkedTreatment&&!sources.some(t=>t.id===linkedTreatment.id)" :value="linkedTreatment.id">{{linkedTreatment.patientName}} · {{linkedTreatment.itemName}}（原治疗交接）</option><option value="">请选择有权的实际治疗</option><option v-for="t in sources" :key="t.id" :value="t.id">{{t.patientName}} · {{t.itemName}} · {{full(t.performedAt)}} · {{t.doctorName}} · {{t.id.slice(0,8).toUpperCase()}}</option></select></label></div><div v-else class="f-context">{{detail.patientName}} · {{detail.itemName}} · {{detail.doctorName}}</div><p v-if="planChoices.loading.value" class="b-help" role="status">正在核对本次治疗的适用方案…</p><p v-if="planChoices.error.value" class="b-alert error" role="alert">{{planChoices.error.value}}</p><button v-if="selectedTreatment" type="button" class="b-button outline small" :disabled="planChoices.loading.value||busy" @click="planChoices.load()">重新读取适用方案</button><label>采用的方案节点<select :disabled="!planChoices.loaded.value||planChoices.loading.value" v-model="form.nodeKey" @change="chooseNode"><option value="">按已核实医生要求人工安排（不采用方案）</option><option v-for="n in nodeOptions" :key="n.key" :value="n.key">{{n.label}}</option></select></label><section v-if="chosenNode" class="fu-node" aria-label="所选节点要求"><strong>方案第 {{chosenNode.p.version_no}} 版{{chosenNode.p.retained_only?'（保留原采用）':''}}</strong><p>时间安排要求：{{chosenNode.n.time_arrangement}}</p><p>联系内容要求：{{chosenNode.n.contact_content}}</p><p>医生要求 / 临床目的：{{chosenNode.n.clinical_purpose}}</p><small>请据此核对具体时间和内容，再确认本次安排。</small></section><template v-if="!form.nodeKey"><label>已核实的具体医生要求<textarea v-model="form.doctorInstruction" rows="3" required maxlength="2000"/></label><p class="b-help">要求医生：{{selectedTreatment?.doctorName||'先选择实际治疗'}}</p><label class="b-checkbox"><input type="checkbox" v-model="form.instructionConfirmed" required/><span>已向对应医生核实具体要求，不由护士或前台代作临床决定。</span></label></template><div class="b-two-fields"><label>核对后的具体计划时间<input type="datetime-local" step="1" v-model="form.plannedAt" required/></label><label>负责人员<select v-model="form.responsibleId" required><option value="">请选择授权人员</option><option v-for="w in workers" :key="w.id" :value="w.id">{{w.name}}</option></select></label></div><label>本次联系内容<textarea v-model="form.plannedContent" required rows="3" maxlength="2000"/></label><label>后续安排（可空）<textarea v-model="form.nextAction" rows="2" maxlength="2000"/></label><label v-if="form.taskId">调整原因<textarea v-model="form.reason" required rows="2"/></label><label class="b-checkbox"><input type="checkbox" v-model="form.arrangementConfirmed" required/><span>已结合该次实际治疗、方案或医生要求核对具体日期、内容和责任人；系统未自动猜测时间。</span></label></template>
 <template v-if="mode==='contact'"><div class="f-context">{{detail.patientName}} · {{detail.itemName}}</div><label>实际联系时间<input type="datetime-local" step="1" v-model="form.contactedAt" required/></label><div class="b-two-fields"><label>实际渠道<select v-model="form.channel" required><option value="">请选择</option><option value="phone">电话</option><option value="message">消息</option><option value="onsite">当面</option><option value="other">其他</option></select></label><label>是否实际联系到患者<select v-model="form.reached" required><option value="">请明确选择</option><option value="no">未联系到</option><option value="yes">已联系到</option></select></label></div><label>真实联系结果及患者反馈<textarea v-model="form.feedback" required rows="3" maxlength="4000"/></label><label>后续安排<textarea v-model="form.nextAction" rows="2" maxlength="2000"/></label><div class="c-subheading"><strong>需要医生判断的问题</strong><button type="button" class="b-button outline small" :disabled="form.problems.length>=5" @click="form.problems.push({problem:'',doctorId:''})"><Plus :size="14"/>加问题</button></div><div v-for="(p,k) in form.problems" :key="k" class="c-treatment-edit"><label>患者反馈中需专业处理的问题<textarea v-model="p.problem" required rows="2" maxlength="2000"/></label><label>转交医生<select v-model="p.doctorId"><option value="">尚待明确转交</option><option :value="detail.doctorId">{{detail.doctorName}}</option></select></label><button type="button" class="f-text" @click="form.problems.splice(k,1)">移除此未保存问题</button></div><p class="b-help">只追加实际联系记录，不执行拨号或发送；成功联系不表示专业问题已解决。</p></template>
 <template v-if="mode==='issue'"><div class="f-context">{{detail.patientName}} · {{detail.itemName}}</div><label>本次跟进结果<select v-model="form.resolve"><option value="no">仅记录转交或跟进，仍待处理</option><option value="yes">已核实医生实际处理并解决该项问题</option></select></label><label>接手 / 处理医生<select v-model="form.doctorId" :required="form.resolve==='yes'"><option value="">尚待明确</option><option :value="detail.doctorId">{{detail.doctorName}}</option></select></label><label>真实跟进或核实的医生结论<textarea v-model="form.conclusion" required rows="3" maxlength="4000"/></label><template v-if="form.resolve==='yes'"><label>医生实际处理时间<input type="datetime-local" step="1" v-model="form.resolvedAt" required/></label><label>已核实的医生处理依据<textarea v-model="form.clinicalBasis" required rows="3" maxlength="4000"/></label><label>相关临床记录（如有，非自动解决依据）<select v-model="form.clinicalRecordId"><option value="">无对应记录，按已核实反馈据实说明</option><option v-for="r in records" :key="r.id" :value="r.id">本就诊病历 · {{full(r.clinicalAt)}} · {{r.completeness==='complete'?'完整':'待补'}}</option></select></label><label class="b-checkbox"><input type="checkbox" v-model="form.feedbackVerified" required/><span>已核实医生真实处理反馈，登记的是医生结论，不是本人代作诊断；转交或回复本身不表示解决。</span></label></template></template>
 <button class="b-button full"  :disabled="busy||!!pending||(mode==='task'&&(!planChoices.loaded.value||planChoices.loading.value||!!planChoices.error.value))">{{busy?'正在保存…':mode==='plan'?'确认保存方案版本':mode==='task'?'确认保存随访安排':mode==='contact'?'确认登记真实联系':mode==='issue'?'确认保存核实跟进':form.enabled?'确认启用':'确认停用新选择'}}</button>
 </form></div>
</div></template>

